Contract ManageLibrarianCRUDService::createLibrarian(librarianid:String,name:String,password:String): Boolean {
          definition:
          librarian:Librarian = Librarian.allInstance()->any(o | o.LibrarianID = librarianid), result:Boolean = false

            precondition:
          librarian.oclIsUndefined() and Librarian.allInstance()->excludes(librarianid)

            postcondition:
          let newLibrarian:Librarian in newLibrarian.oclIsNew() and newLibrarian.LibrarianID = librarianid and newLibrarian.Name = name and newLibrarian.Password = password and result = true and Librarian.allInstance()->includes(newLibrarian)

        }
